const numbers = [12, 45, 7, 89, 23, 56];

// Find the largest number using a loop
let max = numbers[0];
for (let i = 1; i < numbers.length; i++) {
    if (numbers[i] > max) {
        max = numbers[i];
    }
}

// Print each number on its own line
for (let num of numbers) {
    print(num);
}

// Print the largest number
print(max);

